package main

import (
	"os"
	"path/filepath"
	"sync"
	"sync/atomic"
	"testing"

	"github.com/casbin/casbin-authz-plugin/plugin"
	"github.com/docker/go-plugins-helpers/authorization"
)

// TestConcurrentEnforce hammers AuthZReq from many goroutines while a
// separate goroutine repeatedly hot-reloads the policy file, under -race.
//
// It uses two policy files that are swapped into place on disk and reloaded
// via plugin.ReloadPolicy():
//   - "wide"   grants GET /always-allowed and GET /legit-user
//   - "narrow" grants only GET /always-allowed (i.e. /legit-user's grant is
//     revoked)
//
// Correctness requirement under concurrency:
//   - /always-allowed must NEVER be denied, under either policy generation.
//   - /legit-user must NEVER be observed as allowed once the plugin has
//     finished loading the "narrow" policy and no further reload back to
//     "wide" is in flight; more importantly, every single response must
//     match SOME policy generation that was actually active - never a
//     torn/half-updated mix (which would show up as a data race under -race,
//     or as a response inconsistent with any complete policy file).
//
// Run with:
//
//	go test -race -run TestConcurrentEnforce -count=1000 .
func TestConcurrentEnforce(t *testing.T) {
	dir := t.TempDir()
	modelPath := filepath.Join(dir, "model.conf")
	policyPath := filepath.Join(dir, "policy.csv")

	if err := os.WriteFile(modelPath, []byte(basicModel), 0o644); err != nil {
		t.Fatalf("write model: %v", err)
	}

	widePolicy := "p, /always-allowed, GET\np, /legit-user, GET\n"
	narrowPolicy := "p, /always-allowed, GET\n"

	if err := os.WriteFile(policyPath, []byte(widePolicy), 0o644); err != nil {
		t.Fatalf("write initial policy: %v", err)
	}

	p, err := plugin.NewPlugin(modelPath, policyPath)
	if err != nil {
		t.Fatalf("NewPlugin: %v", err)
	}

	const numRequests = 1000
	const numReloads = 10

	var wg sync.WaitGroup
	var alwaysAllowedDenied atomic.Int64
	var legitUserAllowedAfterRevoke atomic.Int64
	var narrowActive atomic.Bool // flips true once the last reload lands on "narrow"

	reqAlwaysAllowed := authorization.Request{RequestURI: "/always-allowed", RequestMethod: "GET"}
	reqLegitUser := authorization.Request{RequestURI: "/legit-user", RequestMethod: "GET"}

	// Requesters: numRequests goroutines firing both URIs concurrently.
	wg.Add(numRequests)
	for i := 0; i < numRequests; i++ {
		go func() {
			defer wg.Done()

			res := p.AuthZReq(reqAlwaysAllowed)
			if !res.Allow {
				alwaysAllowedDenied.Add(1)
			}

			res = p.AuthZReq(reqLegitUser)
			if res.Allow && narrowActive.Load() {
				legitUserAllowedAfterRevoke.Add(1)
			}
		}()
	}

	// Reloader: alternates the on-disk policy between "wide" and "narrow"
	// and reloads numReloads times while requests are in flight.
	wg.Add(1)
	go func() {
		defer wg.Done()
		for i := 0; i < numReloads; i++ {
			var content string
			if i%2 == 0 {
				content = narrowPolicy
			} else {
				content = widePolicy
			}
			if err := os.WriteFile(policyPath, []byte(content), 0o644); err != nil {
				t.Errorf("rewrite policy file: %v", err)
				return
			}
			if err := p.ReloadPolicy(); err != nil {
				t.Errorf("ReloadPolicy: %v", err)
				return
			}
			narrowActive.Store(i%2 == 0)
		}
		// Finish on the wide policy so a trailing check below is meaningful.
		if err := os.WriteFile(policyPath, []byte(widePolicy), 0o644); err != nil {
			t.Errorf("rewrite policy file: %v", err)
			return
		}
		if err := p.ReloadPolicy(); err != nil {
			t.Errorf("final ReloadPolicy: %v", err)
			return
		}
		narrowActive.Store(false)
	}()

	wg.Wait()

	if n := alwaysAllowedDenied.Load(); n != 0 {
		t.Errorf("GET /always-allowed was denied %d times; a policy rule present in every generation must never be denied under concurrent reload", n)
	}
	if n := legitUserAllowedAfterRevoke.Load(); n != 0 {
		t.Errorf("GET /legit-user was allowed %d times while the revoking (narrow) policy was the last one loaded; a stale policy snapshot leaked through a concurrent LoadPolicy", n)
	}

	// Sanity check after all goroutines settle on the final "wide" load: the
	// previously-revoked path must be allowed again, and an anonymous/odd
	// request must still be deniable deterministically (no leftover lock
	// contention or inconsistent state after the reload storm).
	res := p.AuthZReq(reqLegitUser)
	if !res.Allow {
		t.Errorf("GET /legit-user expected allowed after final reload restored the wide policy, got denied: %s", res.Msg)
	}

	res = p.AuthZReq(authorization.Request{RequestURI: "/not-in-any-policy", RequestMethod: "GET"})
	if res.Allow {
		t.Errorf("GET /not-in-any-policy expected denied, got allowed")
	}
}

